begin;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare b jsonb;s jsonb;n jsonb;d jsonb;begin
 b:=public.save_knowledge_base('88000000-0000-4000-8000-000000000001',gen_random_uuid(),'{"action":"create_base","name":"Operations","description":"Synthetic","audienceIds":["00000000-0000-4000-8000-000000000901"]}');
 s:=public.save_knowledge_base('88000000-0000-4000-8000-000000000001',gen_random_uuid(),jsonb_build_object('action','create_node','baseId',b->>'baseId','revision',1,'parentId',null,'kind','folder','name','Section','description',''));
 n:=public.save_knowledge_base('88000000-0000-4000-8000-000000000001',gen_random_uuid(),jsonb_build_object('action','create_node','baseId',b->>'baseId','revision',2,'parentId',s->>'nodeId','kind','text','name','Guide','description','','body',E'  Preserve\ntext\t'));
 perform public.save_knowledge_base('88000000-0000-4000-8000-000000000001',gen_random_uuid(),jsonb_build_object('action','publish_base','baseId',b->>'baseId','revision',3));
 d:=public.read_knowledge_base('88000000-0000-4000-8000-000000000001','node','library',(b->>'baseId')::uuid,(n->>'nodeId')::uuid);
 if d->>'body'<>E'  Preserve\ntext\t'then raise exception 'Text changed: %',d;end if;raise notice 'PASS: real nested text preserves exact whitespace';
 d:=public.read_knowledge_base('88000000-0000-4000-8000-000000000001');if d#>>'{bases,0,revision}'<>'4'then raise exception 'Base revision wrong';end if;raise notice 'PASS: management aggregate revisions and signed catalog';
end$$;
rollback;
begin;
create function pg_temp.check_true(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.expect_state(command text,wanted text,label text)returns void language plpgsql as $$begin begin execute command;exception when others then if sqlstate=wanted then raise notice 'PASS: %',label;return;end if;raise;end;raise exception 'FAIL: % did not reject',label;end$$;
create temp table kb_context(b uuid,f uuid,n uuid,other uuid,deep uuid,op uuid);grant all on kb_context to authenticated;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare t uuid:='88000000-0000-4000-8000-000000000001';b uuid;f uuid;n uuid;other uuid;s jsonb;d jsonb;op uuid:=gen_random_uuid();change jsonb;rev integer;parent uuid;begin
 change:='{"action":"create_base","name":"Rules %_\\ İ","description":"  exact\n","audienceIds":["00000000-0000-4000-8000-000000000901","00000000-0000-4000-8000-000000000904"]}';s:=public.save_knowledge_base(t,op,change);b:=(s->>'baseId')::uuid;
 perform pg_temp.check_true(public.save_knowledge_base(t,op,change)=s,'same UUID payload acknowledges one original write');
 perform pg_temp.check_true((select count(*)=1 from public.knowledge_audit where base_id=b),'UUID retry creates one management audit');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,%L,%L)',t,op,change||'{"name":"Other"}'::jsonb),'40001','same UUID different payload rejected');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,'{"action":"create_base","name":"Invalid","description":"","audienceIds":null}'),'22023','null audience rejected signed RPC');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','create_base','name',chr(13),'description','','audienceIds','[]'::jsonb)),'22023','CR-only name rejected signed RPC');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','create_base','name',repeat('😀',51),'description','','audienceIds','[]'::jsonb)),'22023','UTF16 name bound enforced signed RPC');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','create_base','name',repeat('x',262145),'description','','audienceIds','[]'::jsonb)),'54000','direct signed semantic byte oversize rejected before write');
 perform pg_temp.check_true(workforce_private.knowledge_value_bytes(jsonb_build_object('a','😀','b',jsonb_build_array(null)))=116,'SQL deterministic byte accounting matches recursive value contract');
 s:=public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','create_node','baseId',b,'revision',1,'parentId',null,'kind','folder','name','Root','description',''));f:=(s->>'nodeId')::uuid;
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','create_node','baseId',b,'revision',2,'parentId',null,'kind','text','name','Bad root','description','','body','text')),'22023','root-level text rejected');
 s:=public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','create_node','baseId',b,'revision',2,'parentId',f,'kind','text','name','Text','description','','body',repeat('😀',25000)));n:=(s->>'nodeId')::uuid;
 perform pg_temp.check_true(workforce_private.knowledge_utf16((public.read_knowledge_base(t,'node','manage',b,n))->>'body')=50000,'full valid nonBMP text bound returns exact content');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','edit_node','baseId',b,'revision',3,'nodeId',n,'nodeRevision',1,'kind','folder','name','Bad kind','description','')),'22023','resource kind cannot change');
 for d in select to_jsonb(v)from unnest(array['https://[bad]','https://[::1]/',E'https://example.com\\evil','https://example.0xdeadbeef','https://example.0x','https://xn--a/','https://%65xample.test','https://user:pass@example.test','https://example.test:65536/','https://example.test/bad%ZZ'])v loop
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','create_node','baseId',b,'revision',3,'parentId',f,'kind','link','name','Invalid link','description','','url',d#>>'{}')),'22023','invalid external authority/encoding rejected '||(d#>>'{}'));end loop;
 perform pg_temp.check_true(workforce_private.knowledge_link_valid('https://example.test/guide?q=😀%20x#part')and workforce_private.knowledge_link_valid('http://127.0.0.1:65535/'),'supported literal Unicode tail and decimal IPv4 links validate');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','create_node','baseId','{'||b::text||'}','revision',3,'parentId',f,'kind','folder','name','Malformed id','description','')),'22023','PostgreSQL brace resource UUID syntax rejected');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','create_base','name','Malformed audience','description','','audienceIds',jsonb_build_array('{00000000-0000-4000-8000-000000000901}'))),'22023','PostgreSQL brace audience UUID syntax rejected');
 perform pg_temp.check_true((select count(*)=3 from public.knowledge_audit where base_id=b),'rejected URL and UUID attempts leave audit/revision unchanged');
 s:=public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','create_node','baseId',b,'revision',3,'parentId',null,'kind','folder','name','Other root','description',''));other:=(s->>'nodeId')::uuid;
 s:=public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','order_node','baseId',b,'revision',4,'nodeId',other,'nodeRevision',1,'direction','earlier'));
 d:=public.read_knowledge_base(t,'children','manage',b);perform pg_temp.check_true(d#>>'{nodes,0,id}'=other::text and d#>>'{nodes,1,id}'=f::text,'immediate children use authoritative sibling rank ordering');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','archive_node','baseId',b,'revision',5,'nodeId',f,'nodeRevision',2)),'40001','nonempty folder archive blocked');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','move_node','baseId',b,'revision',5,'nodeId',f,'nodeRevision',2,'parentId',f)),'22023','self parent cycle rejected');
 parent:=f;rev:=5;for i in 2..16 loop s:=public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','create_node','baseId',b,'revision',rev,'parentId',parent,'kind','folder','name','Depth '||i,'description',''));parent:=(s->>'nodeId')::uuid;rev:=rev+1;end loop;
 perform pg_temp.check_true((public.read_knowledge_base(t,'node','manage',b,parent))#>>'{node,depth}'='16','full sixteen-level hierarchy supported');
 perform pg_temp.check_true(jsonb_array_length(workforce_private.knowledge_path(t,b,parent))=16 and workforce_private.knowledge_path(t,b,parent)#>>'{0,id}'=f::text,'bounded path preserves full depth16 root-first ancestry');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','create_node','baseId',b,'revision',rev,'parentId',parent,'kind','folder','name','Too deep','description','')),'22023','seventeenth depth rejected');
 perform public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','archive_node','baseId',b,'revision',rev,'nodeId',parent,'nodeRevision',1));rev:=rev+1;
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','move_node','baseId',b,'revision',rev,'nodeId',f,'nodeRevision',2,'parentId',other)),'22023','archived descendants count toward subtree move depth bound');
 perform public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','publish_base','baseId',b,'revision',rev));rev:=rev+1;
 s:=public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','view','baseId',b,'revision',rev,'nodeId',n,'nodeRevision',1));
 perform pg_temp.check_true(s->>'revision'=rev::text and s->>'eventId'is not null,'explicit view records event without management revision bump');
 perform pg_temp.check_true((public.read_knowledge_base(t,'insights','manage',b,n))#>>'{counts,totalViews}'='1','node insight counts actual node events only');
 d:=public.reconcile_knowledge_view(t,(s->>'operationId')::uuid);perform pg_temp.check_true(d->>'status'='recorded'and(select count(*)=5 from jsonb_object_keys(d)),'reconcile recorded result remains field-free');
 perform pg_temp.check_true(public.reconcile_knowledge_view(t,gen_random_uuid())->>'status'='not_recorded','absent operation reconciles definitively');
 perform public.save_knowledge_base(t,gen_random_uuid(),jsonb_build_object('action','edit_base','baseId',b,'revision',rev,'name','Updated unrelated title','description',''));
 perform pg_temp.check_true(public.save_knowledge_base(t,(s->>'operationId')::uuid,jsonb_build_object('action','view','baseId',b,'revision',rev,'nodeId',n,'nodeRevision',1))=s,'recorded view exact retry acknowledges original event after unrelated base edit');
 perform pg_temp.check_true((select count(*)=1 from public.knowledge_events where base_id=b),'view receipt replay after edit creates no duplicate event');
 perform pg_temp.expect_state(format('select public.save_knowledge_base(%L,gen_random_uuid(),%L)',t,jsonb_build_object('action','view','baseId',b,'revision',rev,'nodeId',n,'nodeRevision',1)),'40001','fresh stale rendered view still rejected');
 insert into kb_context values(b,f,n,other,parent,(s->>'operationId')::uuid);
end$$;
reset role;
-- Controlled chart clock inside this rollback-only test: exercise the actual RPC aggregation
-- against first and repeated Havana midnight, precise UTC timestamps and a DST gap.
do $$declare def text;begin select pg_get_functiondef('public.read_knowledge_base(uuid,text,text,uuid,uuid,uuid,text,text,integer,jsonb)'::regprocedure)into def;execute replace(def,'today:=(statement_timestamp()at time zone tz)::date;','today:=''2026-11-05''::date;');end$$;
update public.tenants set time_zone='America/Havana'where id='88000000-0000-4000-8000-000000000001';
insert into public.knowledge_events(tenant_id,base_id,node_id,actor_id,actor_name,base_revision,node_revision,occurred_at)select '88000000-0000-4000-8000-000000000001',b,n,'00000000-0000-4000-8000-000000000904','Synthetic employee',22,1,v::timestamptz from kb_context cross join unnest(array['2026-11-01T04:30:00.123456Z','2026-11-01T05:30:00.654321Z','2026-11-02T04:59:59.999999Z','2026-11-02T05:00:00.000001Z'])v;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare d jsonb;t uuid:='88000000-0000-4000-8000-000000000001';begin
 d:=public.read_knowledge_base(t,'insights','manage',(select b from kb_context),(select n from kb_context));
 perform pg_temp.check_true((select x->>'views'='3'from jsonb_array_elements(d->'chart')x where x->>'date'='2026-11-01'),'Havana repeated midnight all first-hour events correctly bucket in Nov1');
 perform pg_temp.check_true((select x->>'views'='1'from jsonb_array_elements(d->'chart')x where x->>'date'='2026-11-02'),'Havana end boundary excludes following calendar date');
 perform pg_temp.check_true((select x->>'lastViewedAt'like '%000001%'from jsonb_array_elements(d->'users')x where x->>'actorId'='00000000-0000-4000-8000-000000000904'),'insights preserve precise UTC microseconds');
 perform pg_temp.check_true(d#>>'{counts,totalViews}'='5'and d#>>'{counts,distinctEligibleViewers}'='2','current audience exact view metrics include all retained events');
end$$;
reset role;
update public.tenant_memberships set status='suspended'where tenant_id='88000000-0000-4000-8000-000000000001'and user_id='00000000-0000-4000-8000-000000000904';
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare d jsonb;begin d:=public.read_knowledge_base('88000000-0000-4000-8000-000000000001','insights','manage',(select b from kb_context));perform pg_temp.check_true(d#>>'{counts,eligible}'='1'and d#>>'{counts,unavailable}'='1'and d#>>'{counts,distinctEligibleViewers}'='1','unavailable retained audience excluded from eligible denominator');end$$;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000904',false);
select pg_temp.expect_state(format('select public.read_knowledge_base(%L,''base'',''library'',%L)','88000000-0000-4000-8000-000000000001',(select b from kb_context)),'42501','suspended original actor cannot read retained assignment');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000903',false);
select pg_temp.expect_state(format('select public.read_knowledge_base(%L,''base'',''manage'',%L)','88000000-0000-4000-8000-000000000001',(select b from kb_context)),'42501','manager cannot read management content');
select pg_temp.check_true((select count(*)=0 from public.knowledge_events),'personal signed RLS cannot read event analytics');
reset role;
select pg_temp.check_true(not has_function_privilege('service_role','public.read_knowledge_base(uuid,text,text,uuid,uuid,uuid,text,text,integer,jsonb)','EXECUTE'),'permissive service_role default EXECUTE revoked');
select pg_temp.check_true(not has_table_privilege('authenticated','public.knowledge_events','INSERT'),'signed table grants are SELECT-only');
rollback;

begin;
create function pg_temp.check_true(ok boolean,label text)returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
insert into public.knowledge_bases(id,tenant_id,name,description,status)values('6c000000-0000-4000-8000-000000000001','88000000-0000-4000-8000-000000000001','Calendar and big pages','','published');
insert into public.knowledge_audience(tenant_id,base_id,actor_id,name)values('88000000-0000-4000-8000-000000000001','6c000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000901','Owner');
insert into public.knowledge_nodes(tenant_id,base_id,kind,name,description,depth,rank)select '88000000-0000-4000-8000-000000000001','6c000000-0000-4000-8000-000000000001','folder',E'Literal %_\\ İ','',1,n*1024 from generate_series(1,1005)n;
analyze public.knowledge_nodes;analyze public.knowledge_bases;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare d jsonb;cursor jsonb;total integer:=0;seen uuid[]:='{}';begin loop d:=public.read_knowledge_base('88000000-0000-4000-8000-000000000001','search','manage','6c000000-0000-4000-8000-000000000001',null,null,'all',E'%_\\ İ',100,cursor);perform pg_temp.check_true(d->>'matchedCount'='1005','literal search exact count remains1005 on every keyset page');total:=total+jsonb_array_length(d->'results');seen:=seen||array(select(x#>>'{node,id}')::uuid from jsonb_array_elements(d->'results')x);cursor:=d->'nextCursor';exit when cursor='null'::jsonb;end loop;perform pg_temp.check_true(total=1005 and(select count(distinct id)=1005 from unnest(seen)id),'complete >1000 literal search keyset returns every matching record once');end$$;
do $$declare s jsonb;d jsonb;begin s:=public.save_knowledge_base('88000000-0000-4000-8000-000000000001',gen_random_uuid(),jsonb_build_object('action','create_node','baseId','6c000000-0000-4000-8000-000000000001','revision',1,'parentId',(select id from public.knowledge_nodes where base_id='6c000000-0000-4000-8000-000000000001'order by id limit 1),'kind','text','name','Exact legal controls','description','','body',repeat(chr(1),50000)));d:=public.read_knowledge_base('88000000-0000-4000-8000-000000000001','node','manage','6c000000-0000-4000-8000-000000000001',(s->>'nodeId')::uuid);perform pg_temp.check_true(d->>'body'=repeat(chr(1),50000),'direct RPC semantic budget preserves legal controls despite larger escaped jsonb text');end$$;
reset role;
do $$declare def text;begin select pg_get_functiondef('public.read_knowledge_base(uuid,text,text,uuid,uuid,uuid,text,text,integer,jsonb)'::regprocedure)into def;execute replace(def,'today:=(statement_timestamp()at time zone tz)::date;','today:=''2026-03-15''::date;');end$$;
update public.tenants set time_zone='America/Havana'where id='88000000-0000-4000-8000-000000000001';
insert into public.knowledge_events(tenant_id,base_id,actor_id,actor_name,base_revision,occurred_at)select '88000000-0000-4000-8000-000000000001','6c000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000901','Owner',1,v::timestamptz from unnest(array['2026-03-08T04:59:59.999999Z','2026-03-08T05:00:00.000001Z','2026-03-09T03:59:59.999999Z','2026-03-09T04:00:00.000001Z'])v;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare d jsonb;begin d:=public.read_knowledge_base('88000000-0000-4000-8000-000000000001','insights','manage','6c000000-0000-4000-8000-000000000001');perform pg_temp.check_true((select x->>'views'='2'from jsonb_array_elements(d->'chart')x where x->>'date'='2026-03-08'),'Havana23-hour gap date chart buckets both real boundary events');perform pg_temp.check_true((select x->>'views'='1'from jsonb_array_elements(d->'chart')x where x->>'date'='2026-03-07')and(select x->>'views'='1'from jsonb_array_elements(d->'chart')x where x->>'date'='2026-03-09'),'gap chart preserves separate preceding and following date counts');end$$;
reset role;
do $$declare def text;begin select pg_get_functiondef('public.read_knowledge_base(uuid,text,text,uuid,uuid,uuid,text,text,integer,jsonb)'::regprocedure)into def;execute replace(def,'today:=''2026-03-15''::date;','today:=''2012-01-05''::date;');end$$;
update public.tenants set time_zone='Pacific/Apia'where id='88000000-0000-4000-8000-000000000001';
insert into public.knowledge_events(tenant_id,base_id,actor_id,actor_name,base_revision,occurred_at)select '88000000-0000-4000-8000-000000000001','6c000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000901','Owner',1,v::timestamptz from unnest(array['2011-12-30T09:59:59.999999Z','2011-12-30T10:00:00.000001Z'])v;
set role authenticated;select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000901',false);
do $$declare d jsonb;begin d:=public.read_knowledge_base('88000000-0000-4000-8000-000000000001','insights','manage','6c000000-0000-4000-8000-000000000001');perform pg_temp.check_true((select x->>'views'='0'from jsonb_array_elements(d->'chart')x where x->>'date'='2011-12-30'),'skipped Apia calendar date is genuine zero chart bucket');perform pg_temp.check_true((select x->>'views'='1'from jsonb_array_elements(d->'chart')x where x->>'date'='2011-12-29')and(select x->>'views'='1'from jsonb_array_elements(d->'chart')x where x->>'date'='2011-12-31'),'skipped date adjacent real event buckets retain both records');end$$;
rollback;
